/**
 * Hero — the opening statement of the atlas.
 *
 * The artwork is generated by src/art/schematic.js; there is no photography
 * anywhere in this project.
 */

import { el } from '../core/dom.js';
import { t, pick } from '../core/i18n.js';
import { heroCover } from '../art/schematic.js';
import { CASES } from '../data/catalog.js';
import { REGIONS, ERAS, SYSTEMS } from '../data/taxonomy.js';
import { GLOSSARY } from '../data/glossary.js';
import { LABS } from '../data/labs.js';

/** Distinct official sources cited across the whole catalog. */
function countSources() {
  const seen = new Set();
  for (const item of CASES) {
    for (const src of item.sources || []) seen.add(src.url);
  }
  return seen.size;
}

export function renderHero(host) {
  const stats = [
    [t('hero.stat.cases'), CASES.length],
    [t('hero.stat.types'), SYSTEMS.length],
    [t('hero.stat.terms'), GLOSSARY.length],
    [t('hero.stat.labs'), LABS.length],
    [t('hero.stat.sources'), countSources()],
  ];

  const statList = el('dl.hero-stats');
  for (const [label, value] of stats) {
    statList.append(el('div', {}, [
      el('dt', { text: label }),
      el('dd', { text: String(value) }),
    ]));
  }

  const hero = el('section.hero', { id: 'hero' }, [
    el('div.band-inner', {}, [
      el('div.hero-grid', {}, [
        el('div', {}, [
          el('p.eyebrow', {}, [el('span.dot'), el('span', { text: t('hero.eyebrow') })]),
          el('h1.hero-title', {}, [
            el('span.zh', { text: t('site.title') }),
            el('span.en', {
              html: 'Built in China <span class="accent">Structures &amp; Stories</span>',
            }),
          ]),
          el('p.hero-lede', { text: t('site.tagline') }),
          el('div.hero-actions', {}, [
            el('a.btn.btn-primary', { href: '#/catalog', text: t('hero.cta1') }),
            el('a.btn', { href: '#/labs', text: t('hero.cta2') }),
          ]),
        ]),
        el('div.hero-art', { html: heroCover(560, 420) }),
      ]),
      el('div', { style: { marginTop: 'clamp(2rem, 4vw, 3.4rem)' } }, [statList]),
      el('p.hero-note', { text: t('hero.lede') }),
      el('p.hero-scroll', { text: t('hero.scroll') }),
    ]),
  ]);

  host.append(hero);
  return { stats };
}
